package traits

import (
	"fmt"
	"math"

	corev1 "k8s.io/api/core/v1"
	"sigs.k8s.io/controller-runtime/pkg/client"

	"github.com/go-kure/kure/pkg/kubernetes"
	"github.com/go-kure/kure/pkg/stack"

	"github.com/go-kure/launcher/pkg/errors"
	"github.com/go-kure/launcher/pkg/oam"
)

// SecurityContextHandler handles OAM security-context traits.
//
// The trait declares the workload's required PSA level and applies a matching
// security context to all PodSpec-bearing resources generated by the underlying
// component config. This prevents the downstream runtime's securityContextMutator from overwriting
// them with restricted defaults — the mutator only fires when SecurityContext is nil.
//
// It merges into the security contexts the workload already carries instead of
// replacing them (go-kure/launcher#1171); applyToPodSpec states the rule.
//
// The psaLevel property relaxes namespace PSA admission labels and the downstream runtime's
// CheckPSAMaxProfile gate. It does NOT permit privileged container patterns
// (hostNetwork, hostPID, privileged mode, etc.); those remain controlled by
// SecurityPolicy.AllowPrivileged and related fields.
type SecurityContextHandler struct{}

// CanHandle returns true for the "security-context" trait type.
func (h *SecurityContextHandler) CanHandle(traitType string) bool {
	return traitType == "security-context"
}

// PropertySchema declares the security-context trait's user-facing properties.
func (h *SecurityContextHandler) PropertySchema() map[string]oam.PropertySchema {
	return map[string]oam.PropertySchema{
		"psaLevel":                 {Type: oam.PropertyTypeString, Required: true, Enum: []any{"restricted", "baseline", "privileged"}, Description: "Pod Security Admission level the workload requires (restricted, baseline, or privileged)."},
		"runAsNonRoot":             {Type: oam.PropertyTypeBoolean, Description: "Whether containers must run as a non-root user."},
		"allowPrivilegeEscalation": {Type: oam.PropertyTypeBoolean, Description: "Whether a container process may gain more privileges than its parent."},
		"readOnlyRootFilesystem":   {Type: oam.PropertyTypeBoolean, Description: "Whether the container root filesystem is mounted read-only."},
		"runAsUser":                {Type: oam.PropertyTypeInteger, Description: "UID to run the container process as."},
		"runAsGroup":               {Type: oam.PropertyTypeInteger, Description: "GID to run the container process as."},
		"fsGroup":                  {Type: oam.PropertyTypeInteger, Description: "Supplemental group applied to ownership of mounted volumes."},
	}
}

// Apply wraps app.Config so that Generate() produces securityContext values
// matching the declared psaLevel rather than the downstream-default restricted.
// It does NOT create additional Kubernetes objects.
func (h *SecurityContextHandler) Apply(trait *oam.Trait, app *stack.Application, _ *stack.Bundle) error {
	spec, err := parseSecurityContextProperties(trait.Properties)
	if err != nil {
		return err
	}
	app.Config = wrapIfAugmenter(
		&securityContextConfig{decoratorBase: decoratorBase{Inner: app.Config}, spec: spec},
		app.Config)
	return nil
}

// securityContextSpec holds the parsed trait properties.
type securityContextSpec struct {
	PSALevel                 kubernetes.PSALevel
	RunAsNonRoot             *bool
	AllowPrivilegeEscalation *bool
	ReadOnlyRootFilesystem   *bool
	RunAsUser                *int64
	RunAsGroup               *int64
	FsGroup                  *int64
}

// parseSecurityContextProperties parses trait.Properties and validates constraints.
func parseSecurityContextProperties(props map[string]any) (securityContextSpec, error) {
	var spec securityContextSpec

	levelRaw, ok := props["psaLevel"]
	if !ok {
		return spec, errors.New("security-context: psaLevel is required")
	}
	levelStr, ok := levelRaw.(string)
	if !ok {
		return spec, errors.Errorf("security-context: psaLevel must be a string, got %T", levelRaw)
	}
	switch kubernetes.PSALevel(levelStr) {
	case kubernetes.PSARestricted, kubernetes.PSABaseline, kubernetes.PSAPrivileged:
		spec.PSALevel = kubernetes.PSALevel(levelStr)
	default:
		return spec, errors.Errorf("security-context: psaLevel %q is invalid; must be restricted, baseline, or privileged", levelStr)
	}

	if v, ok := props["runAsNonRoot"]; ok {
		b, ok := v.(bool)
		if !ok {
			return spec, errors.Errorf("security-context: runAsNonRoot must be a bool, got %T", v)
		}
		spec.RunAsNonRoot = &b
	}
	if v, ok := props["allowPrivilegeEscalation"]; ok {
		b, ok := v.(bool)
		if !ok {
			return spec, errors.Errorf("security-context: allowPrivilegeEscalation must be a bool, got %T", v)
		}
		spec.AllowPrivilegeEscalation = &b
	}
	if v, ok := props["readOnlyRootFilesystem"]; ok {
		b, ok := v.(bool)
		if !ok {
			return spec, errors.Errorf("security-context: readOnlyRootFilesystem must be a bool, got %T", v)
		}
		spec.ReadOnlyRootFilesystem = &b
	}
	if v, ok := props["runAsUser"]; ok {
		n, err := toInt64(v)
		if err != nil {
			return spec, errors.Errorf("security-context: runAsUser: %v", err)
		}
		spec.RunAsUser = &n
	}
	if v, ok := props["runAsGroup"]; ok {
		n, err := toInt64(v)
		if err != nil {
			return spec, errors.Errorf("security-context: runAsGroup: %v", err)
		}
		spec.RunAsGroup = &n
	}
	if v, ok := props["fsGroup"]; ok {
		n, err := toInt64(v)
		if err != nil {
			return spec, errors.Errorf("security-context: fsGroup: %v", err)
		}
		spec.FsGroup = &n
	}

	if err := validateSecurityContextSpec(spec); err != nil {
		return spec, err
	}

	return spec, nil
}

// validateSecurityContextSpec rejects overrides that contradict the declared psaLevel.
// readOnlyRootFilesystem is not among them: the Pod Security Standards restricted
// profile does not constrain it, so readOnlyRootFilesystem: false opts a workload
// out of the read-only default while keeping psaLevel restricted
// (go-kure/launcher#998).
func validateSecurityContextSpec(spec securityContextSpec) error {
	if spec.PSALevel == kubernetes.PSARestricted {
		if spec.AllowPrivilegeEscalation != nil && *spec.AllowPrivilegeEscalation {
			return errors.New("security-context: allowPrivilegeEscalation: true is incompatible with psaLevel restricted")
		}
		if spec.RunAsNonRoot != nil && !*spec.RunAsNonRoot {
			return errors.New("security-context: runAsNonRoot: false is incompatible with psaLevel restricted")
		}
	}
	return nil
}

// securityContextConfig wraps an ApplicationConfig and sets PSA-appropriate
// SecurityContext fields on every workload it generates, at Generate time.
type securityContextConfig struct {
	decoratorBase
	spec securityContextSpec
}

// Generate delegates to the inner config and then applies the security context
// overrides to every workload among its objects (workloadRefs).
//
// A component that generates no workload is refused when the trait carries a
// property that is written to a pod spec: it would otherwise build and apply
// to nothing (go-kure/launcher#794, item 14). psaLevel alone is accepted
// there. It declares the level the component requires, which a reader of the
// document can act on for pods the build never sees (a chart Helm installs in
// the cluster, a custom resource a controller turns into pods); the build
// writes no security context for it.
func (c *securityContextConfig) Generate(app *stack.Application) ([]*client.Object, error) {
	objects, err := c.Inner.Generate(app)
	if err != nil {
		return nil, err
	}
	component := decoratedComponent(c.decoratorBase, app)
	workloads := workloadRefs(objects)
	if len(workloads) == 0 {
		if props := c.spec.podSpecProperties(); len(props) > 0 {
			return nil, noWorkloadError("security-context", props, component,
				"psaLevel alone is accepted on such a component, as a declaration of the level it requires")
		}
	}
	for _, w := range workloads {
		where := fmt.Sprintf("component %q, %s %q", component, w.kind, w.name)
		if err := c.spec.applyToPodSpec(w.podSpec, where); err != nil {
			return nil, err
		}
	}
	return objects, nil
}

// podSpecProperties names the properties the trait carries that are written to
// a pod spec, in the schema's order. psaLevel is not one: with none of these
// the trait still states the level, and on a workload it writes that level's
// profile.
func (s *securityContextSpec) podSpecProperties() []string {
	var props []string
	for _, f := range []struct {
		set  bool
		name string
	}{
		{s.RunAsNonRoot != nil, "runAsNonRoot"},
		{s.AllowPrivilegeEscalation != nil, "allowPrivilegeEscalation"},
		{s.ReadOnlyRootFilesystem != nil, "readOnlyRootFilesystem"},
		{s.RunAsUser != nil, "runAsUser"},
		{s.RunAsGroup != nil, "runAsGroup"},
		{s.FsGroup != nil, "fsGroup"},
	} {
		if f.set {
			props = append(props, f.name)
		}
	}
	return props
}

// applyToPodSpec merges the trait into the security contexts on the pod and on
// every container (including init containers), then checks the result against
// the declared level (checkPSALevel). Non-nil contexts are set so that the
// downstream runtime's securityContextMutator (which only fires when
// SecurityContext is nil) skips them. where names the workload in an error.
//
// The merge is field by field (go-kure/launcher#1171). Three layers, highest
// first:
//
//  1. An explicit trait property (the seven in PropertySchema). The trait
//     owns these fields. An authored value that differs is an error, because
//     either one would win silently; an equal one is fine. A container-level
//     runAsUser or runAsGroup that differs from the trait's pod-level value is
//     the same error, since the container value overrides the pod value at
//     run time.
//  2. The value the component, manifests source or chart authored. Every
//     field the trait has no property for (capabilities.add, privileged,
//     seccomp Localhost, seLinuxOptions, appArmorProfile, windowsOptions,
//     procMount, sysctls, supplementalGroups, ...) is only ever read from
//     here, never written or dropped.
//  3. The psaLevel profile, for a field still unset: restricted fills in the
//     kure restricted profile, baseline and privileged add nothing.
//
// Each context is a copy: the builders' pointers and the authored object's
// pointers do not end up shared between two containers, the pod and the config.
//
// A pod that declares `os.name: windows` (go-kure/launcher#342's pod-level
// `os` property) gets the Windows-legal subset instead: the API rejects a
// Windows pod carrying seccompProfile, capabilities, allowPrivilegeEscalation,
// readOnlyRootFilesystem, runAsUser/runAsGroup or fsGroup, so writing the
// restricted Linux profile here would emit a workload Kubernetes refuses —
// the component-side OS validation cannot see it, because it runs before this
// decorator. Upstream Pod Security Admission takes the same route, skipping
// the Linux-only controls for Windows pods. An override the author set
// explicitly that Windows forbids is an error rather than a silent drop.
func (s *securityContextSpec) applyToPodSpec(podSpec *corev1.PodSpec, where string) error {
	windows := podSpec.OS != nil && podSpec.OS.Name == corev1.Windows
	if windows {
		if err := s.rejectWindowsIllegalOverrides(); err != nil {
			return err
		}
	}

	authoredPod := podSpec.SecurityContext
	pod, err := s.mergePodSecurityContext(authoredPod, windows, where+", pod")
	if err != nil {
		return err
	}
	podSpec.SecurityContext = pod

	for i := range podSpec.Containers {
		c := &podSpec.Containers[i]
		if c.SecurityContext, err = s.mergeContainerSecurityContext(c.SecurityContext, authoredPod, pod, windows,
			fmt.Sprintf("%s, container %q", where, c.Name)); err != nil {
			return err
		}
	}
	for i := range podSpec.InitContainers {
		c := &podSpec.InitContainers[i]
		if c.SecurityContext, err = s.mergeContainerSecurityContext(c.SecurityContext, authoredPod, pod, windows,
			fmt.Sprintf("%s, init container %q", where, c.Name)); err != nil {
			return err
		}
	}
	return checkPSALevel(s.PSALevel, podSpec, windows, where)
}

// mergePodSecurityContext returns a copy of authored (nil when none) with the
// trait's pod-level properties and the level's pod defaults merged in
// (applyToPodSpec states the precedence). windows selects the Windows-legal
// subset: of everything the Linux profiles set, only runAsNonRoot is accepted
// on a Windows pod.
func (s *securityContextSpec) mergePodSecurityContext(authored *corev1.PodSecurityContext, windows bool, where string) (*corev1.PodSecurityContext, error) {
	sc := authored.DeepCopy()
	if sc == nil {
		sc = &corev1.PodSecurityContext{}
	}
	if err := setExplicit(&sc.RunAsNonRoot, s.RunAsNonRoot, "runAsNonRoot", where); err != nil {
		return nil, err
	}
	if !windows {
		if err := setExplicit(&sc.RunAsUser, s.RunAsUser, "runAsUser", where); err != nil {
			return nil, err
		}
		if err := setExplicit(&sc.RunAsGroup, s.RunAsGroup, "runAsGroup", where); err != nil {
			return nil, err
		}
		if err := setExplicit(&sc.FSGroup, s.FsGroup, "fsGroup", where); err != nil {
			return nil, err
		}
	}
	if s.PSALevel == kubernetes.PSARestricted {
		def := kubernetes.RestrictedPodSecurityContext()
		if sc.RunAsNonRoot == nil {
			sc.RunAsNonRoot = def.RunAsNonRoot
		}
		if !windows && sc.SeccompProfile == nil {
			sc.SeccompProfile = def.SeccompProfile
		}
	}
	return sc, nil
}

// mergeContainerSecurityContext is mergePodSecurityContext for one container.
// pod is the merged pod-level context: a trait-set pod-level runAsUser or
// runAsGroup is shadowed by a different container-level value, which is an
// error, and a restricted container with no seccomp profile of its own takes
// the pod's rather than shadowing an authored pod-level profile with
// RuntimeDefault.
func (s *securityContextSpec) mergeContainerSecurityContext(authored *corev1.SecurityContext, authoredPod, pod *corev1.PodSecurityContext, windows bool, where string) (*corev1.SecurityContext, error) {
	sc := authored.DeepCopy()
	if sc == nil {
		sc = &corev1.SecurityContext{}
	}
	if err := setExplicit(&sc.RunAsNonRoot, s.RunAsNonRoot, "runAsNonRoot", where); err != nil {
		return nil, err
	}
	if !windows {
		if err := setExplicit(&sc.AllowPrivilegeEscalation, s.AllowPrivilegeEscalation, "allowPrivilegeEscalation", where); err != nil {
			return nil, err
		}
		if err := setExplicit(&sc.ReadOnlyRootFilesystem, s.ReadOnlyRootFilesystem, "readOnlyRootFilesystem", where); err != nil {
			return nil, err
		}
		if err := refuseShadow(s.RunAsUser, sc.RunAsUser, "runAsUser", where); err != nil {
			return nil, err
		}
		if err := refuseShadow(s.RunAsGroup, sc.RunAsGroup, "runAsGroup", where); err != nil {
			return nil, err
		}
	}
	if s.PSALevel == kubernetes.PSARestricted {
		def := kubernetes.RestrictedSecurityContext()
		if sc.RunAsNonRoot == nil {
			sc.RunAsNonRoot = def.RunAsNonRoot
		}
		if !windows {
			if sc.AllowPrivilegeEscalation == nil {
				sc.AllowPrivilegeEscalation = def.AllowPrivilegeEscalation
			}
			if sc.ReadOnlyRootFilesystem == nil {
				sc.ReadOnlyRootFilesystem = def.ReadOnlyRootFilesystem
			}
			switch {
			case sc.Capabilities == nil:
				sc.Capabilities = def.Capabilities
			case !dropsAll(sc.Capabilities):
				sc.Capabilities.Drop = append(sc.Capabilities.Drop, def.Capabilities.Drop...)
			}
			if sc.SeccompProfile == nil {
				if pod.SeccompProfile != nil {
					sc.SeccompProfile = pod.SeccompProfile.DeepCopy()
				} else {
					sc.SeccompProfile = def.SeccompProfile
				}
			}
		}
	}
	if !windows {
		if err := s.refuseContradictions(authored, sc, authoredPod, pod, where); err != nil {
			return nil, err
		}
	}
	return sc, nil
}

// refuseContradictions rejects a merged container context that Kubernetes
// refuses at admission or the kubelet cannot start, at every psaLevel. The
// trait adds allowPrivilegeEscalation and runAsNonRoot to a context the
// component parser checked before the trait ran, so those checks
// (validateEffectiveRunAsUser and the privileged and CAP_SYS_ADMIN pair in the
// components package) cannot see a contradiction the trait introduces. Each
// error names the trait property, the level default or the workload as the
// source of each side (authored is the context before the merge).
func (s *securityContextSpec) refuseContradictions(authored, sc *corev1.SecurityContext, authoredPod, pod *corev1.PodSecurityContext, where string) error {
	if sc.AllowPrivilegeEscalation != nil && !*sc.AllowPrivilegeEscalation {
		src := s.sourceOf(s.AllowPrivilegeEscalation != nil, authored != nil && authored.AllowPrivilegeEscalation != nil, "allowPrivilegeEscalation: false")
		if sc.Privileged != nil && *sc.Privileged {
			return errors.Errorf("security-context: %s: %s, and the workload sets privileged: true, which makes allowPrivilegeEscalation true; set one of them in the workload", where, src)
		}
		if sc.Capabilities != nil {
			for _, c := range sc.Capabilities.Add {
				if c == "CAP_SYS_ADMIN" {
					return errors.Errorf("security-context: %s: %s, and the workload adds capability CAP_SYS_ADMIN, which Kubernetes refuses together with it; set one of them in the workload", where, src)
				}
			}
		}
	}
	// The kubelet takes the container's value, else the pod's. The trait writes
	// runAsNonRoot on both levels and runAsUser on the pod only, so the source
	// of each effective value follows the level it was taken from.
	user, userFrom := sc.RunAsUser, "the workload sets runAsUser: 0 on the container"
	if user == nil && pod != nil {
		user = pod.RunAsUser
		userFrom = "the workload sets runAsUser: 0 on the pod"
		if s.RunAsUser != nil {
			userFrom = "the trait sets runAsUser: 0"
		}
	}
	nonRoot, nonRootFrom := sc.RunAsNonRoot, ""
	switch {
	case sc.RunAsNonRoot == nil && pod != nil:
		nonRoot = pod.RunAsNonRoot
		nonRootFrom = s.sourceOf(s.RunAsNonRoot != nil, authoredPod != nil && authoredPod.RunAsNonRoot != nil, "runAsNonRoot: true", "on the pod")
	default:
		nonRootFrom = s.sourceOf(s.RunAsNonRoot != nil, authored != nil && authored.RunAsNonRoot != nil, "runAsNonRoot: true", "on the container")
	}
	if user != nil && *user == 0 && nonRoot != nil && *nonRoot {
		return errors.Errorf("security-context: %s: %s, and %s; the kubelet refuses to start a container with UID 0 under runAsNonRoot, so set a non-zero runAsUser or runAsNonRoot: false", where, nonRootFrom, userFrom)
	}
	return nil
}

// sourceOf says where a merged value came from: the trait property, the
// workload that authored it, or the psaLevel profile's default.
// level (optional) says where the workload set it: "on the pod" or "on the
// container".
func (s *securityContextSpec) sourceOf(fromTrait, authored bool, what string, level ...string) string {
	at := ""
	if len(level) > 0 {
		at = " " + level[0]
	}
	switch {
	case fromTrait:
		return "the trait sets " + what
	case authored:
		return "the workload sets " + what + at
	default:
		return fmt.Sprintf("psaLevel %s sets %s", s.PSALevel, what)
	}
}

// setExplicit writes the trait's value into *dst. A nil value is no property
// and leaves *dst alone. A value already there that differs is an error: the
// trait and the workload disagree, and neither may win without a word. The
// value is copied, so the trait's pointer is shared with nothing.
func setExplicit[T comparable](dst **T, val *T, field, where string) error {
	if val == nil {
		return nil
	}
	if *dst != nil && **dst != *val {
		return errors.Errorf("security-context: %s: %s: the trait sets %v, the workload sets %v; set it in one place", where, field, *val, **dst)
	}
	v := *val
	*dst = &v
	return nil
}

// refuseShadow errors when a container sets a value that differs from the
// trait's pod-level value for the same field: the container value would win at
// run time, so the trait's property would apply to nothing the pod runs.
func refuseShadow[T comparable](trait, container *T, field, where string) error {
	if trait == nil || container == nil || *trait == *container {
		return nil
	}
	return errors.Errorf("security-context: %s: %s: the trait sets %v on the pod, the container sets %v and overrides it; set it in one place", where, field, *trait, *container)
}

func dropsAll(c *corev1.Capabilities) bool {
	for _, cp := range c.Drop {
		if cp == "ALL" {
			return true
		}
	}
	return false
}

// rejectWindowsIllegalOverrides errors when the trait carries an explicit
// override that a Windows pod may not set. runAsNonRoot is the one override
// Windows accepts, so it is absent from this list.
func (s *securityContextSpec) rejectWindowsIllegalOverrides() error {
	for _, f := range []struct {
		set  bool
		name string
	}{
		{s.AllowPrivilegeEscalation != nil, "allowPrivilegeEscalation"},
		{s.ReadOnlyRootFilesystem != nil, "readOnlyRootFilesystem"},
		{s.RunAsUser != nil, "runAsUser"},
		{s.RunAsGroup != nil, "runAsGroup"},
		{s.FsGroup != nil, "fsGroup"},
	} {
		if f.set {
			return errors.Errorf("security-context: %s cannot be set on a component with os.name: windows; Kubernetes rejects that field on a Windows pod", f.name)
		}
	}
	return nil
}

func toInt64(v any) (int64, error) {
	return oam.IntegerInRange(v, math.MinInt64, math.MaxInt64)
}
